# Conformance with DataComPy. Fixtures and expected results are generated by
# data-raw/datacompy_fixtures.py; DataComPy's recorded results are the
# expected values, never recomputed here. See data-raw/README.md for the
# semantics covered and those excluded.

fixture_dir <- test_path("fixtures", "datacompy")
manifest <- utils::read.csv(file.path(fixture_dir, "manifest.csv"), stringsAsFactors = FALSE)

read_fixture <- function(file, types) {
  header <- names(utils::read.csv(file.path(fixture_dir, file), nrows = 0, check.names = FALSE))
  col_classes <- ifelse(header %in% types$variable, types$type[match(header, types$variable)], "character")
  tibble::as_tibble(utils::read.csv(
    file.path(fixture_dir, file),
    colClasses = col_classes, na.strings = "NA", check.names = FALSE
  ))
}

# Matched observations: every Base observation that isn't Unmatched. Holds
# because the fixtures have no Duplicate IDs; derived from public results so
# the tests don't depend on the Listing's layout.
matched_count <- function(base, unmatched) {
  nrow(base) - sum(unmatched$dataset == "Base")
}

sort_by_ids <- function(df, cols) {
  df <- df[do.call(order, unname(as.list(df[cols]))), , drop = FALSE]
  rownames(df) <- NULL
  df
}

for (i in seq_len(nrow(manifest))) {
  fx <- as.list(manifest[i, ])
  types <- utils::read.csv(file.path(fixture_dir, paste0(fx$dataset, "_types.csv")), stringsAsFactors = FALSE)
  id <- strsplit(fx$id, " ", fixed = TRUE)[[1]]
  base <- read_fixture(paste0(fx$dataset, "_base.csv"), types)
  compare <- read_fixture(paste0(fx$dataset, "_compare.csv"), types)
  expected_unmatched <- read_fixture(paste0(fx$fixture, "_unmatched.csv"), types)
  expected_unequal <- read_fixture(paste0(fx$fixture, "_unequal.csv"), types)
  expected_counts <- utils::read.csv(
    file.path(fixture_dir, paste0(fx$fixture, "_unequal_counts.csv")), stringsAsFactors = FALSE
  )

  local({
    fx <- fx
    id <- id
    base <- base
    compare <- compare
    expected_unmatched <- expected_unmatched
    expected_unequal <- expected_unequal
    expected_counts <- expected_counts

    run <- function(as_backend) {
      df_compare(
        as_backend(base), as_backend(compare), id = id,
        method = fx$method, criterion = fx$criterion
      )
    }

    test_each_backend(paste0(fx$fixture, ": Matched and Unmatched observations agree with DataComPy"), {
      res <- run(as_backend)
      unmatched <- unmatched_rows(res)

      expect_identical(matched_count(base, unmatched), as.integer(fx$matched))
      expect_identical(sum(unmatched$dataset == "Base"), as.integer(fx$unmatched_base))
      expect_identical(sum(unmatched$dataset == "Compare"), as.integer(fx$unmatched_compare))
      expect_equal(
        sort_by_ids(as.data.frame(unmatched), c("dataset", id)),
        sort_by_ids(as.data.frame(expected_unmatched), c("dataset", id))
      )
    })

    test_each_backend(paste0(fx$fixture, ": Unequal values agree with DataComPy"), {
      unequal <- differences(run(as_backend))
      counts <- table(factor(unequal$variable, levels = expected_counts$variable))

      expect_identical(as.integer(counts), as.integer(expected_counts$unequal))
      expect_equal(
        sort_by_ids(as.data.frame(unequal[c(id, "variable")]), c("variable", id)),
        sort_by_ids(as.data.frame(expected_unequal[c(id, "variable")]), c("variable", id))
      )
    })
  })
}
